package wpimport

const featuresJS = `(function(){'use strict';
function text(tag,value){var n=document.createElement(tag);n.textContent=value==null?'':String(value);return n}
function date(value){var raw=String(value||''),d=new Date(raw.replace(' ','T'));var n=text('time',isNaN(d)?raw:d.toLocaleDateString('en-GB',{day:'numeric',month:'long',year:'numeric',timeZone:'UTC'}));n.setAttribute('datetime',raw);return n}
function missing(e){return e&&(e.status===404||e.statusCode===404||/resource.*(missing|not_found)|resource_not_found|not_found.*resource/.test(e.code||e.message||''))}
function error(out,e){out.textContent=missing(e)?'This form is not switched on yet.':'Not sent: '+(e&&e.message||String(e)||'please try again')}
function table(resource,name){return SH.storage.sqlite(resource).table(name)}
function fields(form){var o={};new FormData(form).forEach(function(v,k){if(o[k]!==undefined)o[k]=[].concat(o[k],v);else o[k]=v});return o}
function value(o,key){if(o[key])return o[key];var found=Object.keys(o).find(function(k){return k.toLowerCase().includes(key)});return found?o[found]:''}
function send(form,action){var busy=false;form.addEventListener('submit',async function(e){e.preventDefault();if(busy)return;busy=true;var out=form.querySelector('[role=status]'),button=form.querySelector('button');button.disabled=true;out.textContent='Sending…';try{await action(fields(form),out);form.reset()}catch(e){error(out,e)}finally{busy=false;button.disabled=false}})}
function listing(t,list,where){return t.list({order:'id',desc:1,limit:100,where:where||{}}).then(function(result){list.textContent='';SH.storage.toObjects(result).forEach(function(row){var item=text('article','');item.append(text('strong',row.name),date(row.created_at),text('p',row.message));list.append(item)})})}
function wire(){document.querySelectorAll('form[data-sh-feature]').forEach(function(form){var kind=form.dataset.shFeature,page=form.dataset.page||location.pathname,out=form.querySelector('[role=status]');if(!out){out=text('p','');out.setAttribute('role','status');form.append(out)}var resource=kind==='contact'?'messages':kind==='subscribe'?'subscribers':kind,tn=kind==='contact'?'messages':kind==='subscribe'?'subscribers':'entries',t=table(resource,tn),list=form.closest('section').querySelector('[data-sh-list]');if(kind==='comments'||kind==='guestbook')listing(t,list,kind==='comments'?{page:page}:{}).catch(function(e){error(out,e)});send(form,async function(o,status){var data;if(kind==='contact')data={page:page,form:form.dataset.form||'',name:value(o,'name'),email:value(o,'email'),message:value(o,'message'),fields:JSON.stringify(o)};else if(kind==='subscribe')data={email:o.email,page:page};else if(kind==='comments')data={page:page,name:o.name,message:o.message};else data={name:o.name,message:o.message};await t.add(data);status.textContent=form.dataset.moderated==='true'?'Thanks, your '+(kind==='guestbook'?'entry':'comment')+' shows once it is approved.':'Thanks, sent.';if((kind==='comments'||kind==='guestbook')&&form.dataset.moderated!=='true')listing(t,list,kind==='comments'?{page:page}:{}).catch(function(e){error(status,e)})})});
 document.querySelectorAll('section[data-sh-feature="forum"]').forEach(function(root,index){var t=table('forum','posts'),topics=root.querySelector('[data-sh-topics]'),thread=root.querySelector('[data-sh-thread]'),out=root.querySelector('[data-sh-error]'),newForm=root.querySelector('[data-sh-new]'),reply=root.querySelector('[data-sh-reply]'),active=0,rows=[];var signin=root.querySelector('[data-sh-signin]');signin.id='sh-forum-signin-'+index;SH.mount('#'+signin.id);
 function rowNode(row){var n=text('article','');n.append(text('strong',row.name),date(row.created_at),text('p',row.message));if(row.mine){var b=text('button','Delete'),busy=false;b.addEventListener('click',async function(){if(busy)return;busy=true;b.disabled=true;try{await t.delete(row.id);await load()}catch(e){error(out,e)}finally{busy=false;b.disabled=false}});n.append(b)}return n}
 function show(){thread.textContent='';if(!active){reply.hidden=true;return}rows.filter(function(r){return Number(r.id)===active||Number(r.topic)===active}).sort(function(a,b){return a.id-b.id}).forEach(function(r){thread.append(rowNode(r))});reply.hidden=false}
 async function load(){var result=await t.list({order:'id',desc:1,limit:100});rows=SH.storage.toObjects(result);topics.textContent='';var top=rows.filter(function(r){return !Number(r.topic)});if(!top.length)topics.append(text('p','No topics yet. Start the first one.'));top.forEach(function(row){var b=text('button',row.title+' - '+row.name+' - '+rows.filter(function(r){return Number(r.topic)===Number(row.id)}).length+' replies - '+date(row.created_at).textContent);b.addEventListener('click',function(){active=Number(row.id);show()});topics.append(b)});show()}
 send(newForm,async function(o,status){await SH.requireSignIn();await t.add({topic:0,title:o.title,name:o.name,message:o.message});status.textContent='Topic posted.';load().catch(function(e){error(out,e)})});send(reply,async function(o,status){await SH.requireSignIn();await t.add({topic:active,name:o.name,message:o.message});status.textContent='Reply posted.';load().catch(function(e){error(out,e)})});load().catch(function(e){error(out,e)})});
 var buy=document.querySelectorAll('[data-sh-feature="buy"]');if(buy.length){fetch(payment||new URL('sh-import/payment-links.json',document.baseURI)).then(function(r){if(!r.ok)throw Error('Payment links unavailable');return r.json()}).then(function(links){buy.forEach(function(b){var u=links[b.dataset.product];if(u&&/^https:\/\//.test(u)){b.href=u;b.hidden=false}})}).catch(function(){})}}
 var script=document.currentScript,payment=script?new URL('payment-links.json',script.src):null;

 if(window.SH&&SH.storage)wire();else window.addEventListener('load',function(){if(window.SH&&SH.storage)wire();else document.querySelectorAll('[role=status]').forEach(function(n){n.textContent='Not sent: sign-in tools could not be loaded.'})})
})();`
